export const VOLT_STORM=Object.freeze({strikeDelay:3,strikeCooldown:8,strikeDamage:320,strikeRadius:7,strikeEdge:.35,strikeRange:100,ultimateCost:RUNNER_ENERGY.capacity*2/3,ultimateCooldown:16,orbRadius:1.25,orbSpeed:4,orbEnergy:100,orbLife:0,orbDrain:1,zapRange:16,zapInterval:.45,zapCost:6,zapDamage:65,zapTargets:3,rechargeFactor:.5});
export class RunnerStorm {
 constructor({getUnits,getSections,onHit=()=>0,onEvent=()=>{},groundHeight=()=>.08,bounds={minX:-56,maxX:56,minZ:-56,maxZ:56}}){Object.assign(this,{getUnits,getSections,onHit,onEvent,groundHeight,bounds});this.reset();}
 reset(){this.orb=null;this.strike=null;this.events=[];this.strikeCooldown=this.ultimateCooldown=this.strikes=this.casts=this.zaps=this.damage=this.recharged=0;this.sequence=0;}
 event(e){this.events.push({...e,age:0});if(this.events.length>32)this.events.shift();}
 clear(a,b,radius=0){return !traceImpact(a,b,{sections:this.getSections(),ground:false,radius});}
 callStrike(point){if(this.strike||this.strikeCooldown>1e-8||!point)return false;this.strike={point:point.clone(),remaining:VOLT_STORM.strikeDelay};this.strikeCooldown=VOLT_STORM.strikeCooldown;this.onEvent('warning');return true;}
 launch(from,direction,energy){const c=VOLT_STORM;if(this.ultimateCooldown>1e-8||energy.amount<c.ultimateCost-1e-8)return false;const dir=direction.clone().normalize(),position=from.clone().addScaledVector(dir,c.orbRadius+1);position.y=Math.max(position.y,this.groundHeight(position.x,position.z)+c.orbRadius+.2);if(!this.clear(from,position,.4)||!this.clear(position,position,c.orbRadius))return false;if(!energy.spend(c.ultimateCost))return false;if(this.orb)this.event({kind:'fade',point:this.orb.position.clone()});this.orb={id:++this.sequence,position,direction:dir,energy:c.orbEnergy,age:0,zapClock:0,parked:false,flash:0};this.ultimateCooldown=c.ultimateCooldown;this.casts++;this.onEvent('launch');return true;}
 recharge(power){const o=this.orb;if(!o||power<=0)return 0;const gain=Math.min(VOLT_STORM.orbEnergy-o.energy,power*VOLT_STORM.rechargeFactor);o.energy+=gain;o.flash=1;this.recharged+=gain;return gain;}
 rechargeBlast(origin,radius,power){if(this.orb&&origin.distanceTo(this.orb.position)<=radius+VOLT_STORM.orbRadius&&this.clear(origin,this.orb.position))return this.recharge(power);return 0;}
 trace(a,b,radius=0){const o=this.orb;if(!o)return null;const delta=b.clone().sub(a),m=a.clone().sub(o.position),r=VOLT_STORM.orbRadius+radius,c=m.lengthSq()-r*r;let t=0;if(c>0){const aa=delta.lengthSq(),bb=m.dot(delta),d=bb*bb-aa*c;if(aa<1e-12||d<0)return null;t=(-bb-Math.sqrt(d))/aa;if(t<0||t>1)return null;}return{kind:'volt-orb',voltOrb:true,energyOrb:o,t,point:a.clone().addScaledVector(delta,t)};}
 sweepHit(from,direction,c){const o=this.orb;if(!o)return null;const d=o.position.clone().sub(from),flat=d.clone().setY(0),forward=direction.clone().setY(0).normalize();if(d.length()>c.range+VOLT_STORM.orbRadius||Math.abs(d.y)>c.vertical+VOLT_STORM.orbRadius||flat.lengthSq()>1e-6&&flat.normalize().dot(forward)<Math.cos(c.arc*Math.PI/360)||!this.clear(from,o.position))return null;return{kind:'volt-orb',voltOrb:true,point:o.position.clone()};}
 strikeNow(point){const c=VOLT_STORM,origin=point.clone().add(new THREE.Vector3(0,.4,0));this.strikes++;this.event({kind:'strike',point:point.clone()});this.onEvent('strike');this.rechargeBlast(origin,c.strikeRadius,c.strikeDamage);for(const h of massContacts(origin,this.getUnits(),c.strikeRadius)){if(!this.clear(origin,h.point))continue;const hit=traceImpact(origin,h.point,{sections:this.getSections(),targets:[h.unit],ground:false,radius:.02});if(hit?.unit!==h.unit)continue;const power=c.strikeDamage*(1-(1-c.strikeEdge)*h.distance/c.strikeRadius);this.damage+=this.onHit(hit,power,'sky-strike')||0;}}
 update(dt){if(!(dt>0))return;const c=VOLT_STORM;dt=Math.max(0,dt);for(const e of this.events)e.age+=dt;this.events=this.events.filter(e=>e.age<(e.kind==='strike'?.65:.25));this.strikeCooldown=Math.max(0,this.strikeCooldown-dt);this.ultimateCooldown=Math.max(0,this.ultimateCooldown-dt);
  if(this.strike){this.strike.remaining-=dt;if(this.strike.remaining<=1e-9){const point=this.strike.point;this.strike=null;this.strikeNow(point);}}
  const o=this.orb;if(!o)return;o.age+=dt;o.flash=Math.max(0,o.flash-dt*3);o.energy=Math.max(0,o.energy-c.orbDrain*dt);if(c.orbLife>0&&o.age>=c.orbLife||o.energy<=1e-8){this.event({kind:'fade',point:o.position.clone()});this.orb=null;return;}
  if(!o.parked){const next=o.position.clone().addScaledVector(o.direction,c.orbSpeed*dt);next.y=Math.max(next.y,this.groundHeight(next.x,next.z)+c.orbRadius+.2);if(next.x<this.bounds.minX+c.orbRadius||next.x>this.bounds.maxX-c.orbRadius||next.z<this.bounds.minZ+c.orbRadius||next.z>this.bounds.maxZ-c.orbRadius||!this.clear(o.position,next,c.orbRadius))o.parked=true;else o.position.copy(next);}
  o.zapClock-=dt;while(o.zapClock<=1e-9){o.zapClock+=c.zapInterval;const targets=massContacts(o.position,this.getUnits(),c.zapRange).sort((a,b)=>a.distance-b.distance),selected=[];for(const h of targets){const hit=traceImpact(o.position,h.point,{sections:this.getSections(),targets:[h.unit],ground:false,radius:.02});if(hit?.unit===h.unit)selected.push(hit);if(selected.length>=c.zapTargets)break;}for(const hit of selected){if(o.energy<c.zapCost)break;o.energy-=c.zapCost;this.zaps++;this.damage+=this.onHit(hit,c.zapDamage,'ball-lightning-'+o.id+'-'+this.zaps)||0;this.event({kind:'zap',from:o.position.clone(),point:new THREE.Vector3().copy(hit.point)});}if(selected.length)this.onEvent('zap');}
  if(o.energy<=1e-8){this.event({kind:'fade',point:o.position.clone()});this.orb=null;}
 }
 diagnostics(){return{strike:this.strike?{point:this.strike.point.toArray(),remaining:this.strike.remaining}:null,strikeCooldown:this.strikeCooldown,ultimateCooldown:this.ultimateCooldown,strikes:this.strikes,casts:this.casts,zaps:this.zaps,damage:this.damage,recharged:this.recharged,orb:this.orb?{position:this.orb.position.toArray(),energy:this.orb.energy,maxEnergy:VOLT_STORM.orbEnergy,age:this.orb.age,parked:this.orb.parked}:null};}
}
